def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find horizontal bars, including their internal gaps.
    bars = []
    for r, row in enumerate(grid):
        occupied = [c for c, v in enumerate(row) if v]
        if len(occupied) >= 2:
            bars.append((r, occupied[0], occupied[-1]))

    # Gaps in the horizontal bars identify vertical tracks. A track extends
    # upward from its lower seed, taking the color of each bar it crosses.
    tracks = set()
    for r, left, right in bars:
        for c in range(left + 1, right):
            if grid[r][c] == 0:
                tracks.add(c)

    for c in tracks:
        seed_rows = [r for r in range(h) if grid[r][c] != 0]
        if not seed_rows:
            continue
        bottom = max(seed_rows)

        for r in range(bottom - 1, -1, -1):
            if out[r][c] != 0:
                continue

            # At a bar row, inherit the color of the horizontal portion on
            # the left of the gap; between bars, carry the last such color.
            color = None
            for br, left, right in bars:
                if br >= r and br < bottom and left < c < right:
                    if grid[br][c] == 0:
                        color = next(
                            (grid[br][x] for x in range(c - 1, left - 1, -1)
                             if grid[br][x] != 0),
                            None
                        )
                        break
            if color is None:
                color = next((grid[rr][c] for rr in range(r + 1, h)
                              if grid[rr][c] != 0), None)
            if color is not None:
                out[r][c] = color

    return out
